import rclpy
from rclpy.node import Node
from cm_msgs.srv import CommonStreamRos2
import json
import time

# 运行之前需要
# ros2 control switch_controllers --activate moveit_right_arm_controller moveit_left_arm_controller
# 此脚本实现等同于以下命令：
# ros2 service call /joint_space_control cm_msgs/srv/CommonStreamRos2 "msg_id: ''
# json_data: '{\"group\": \"dual_arm\",\"random\":true}'"

class DualArmRandomRunner(Node):
    def __init__(self):
        super().__init__('dual_arm_random_runner')
        
        # 声明 ROS2 参数
        self.declare_parameter('num_runs', 10)  # 默认值：10次
        self.declare_parameter('interval', 1.0)  # 默认值：1.0秒
        
        # 获取参数值
        self.num_runs = self.get_parameter('num_runs').get_parameter_value().integer_value
        self.interval = self.get_parameter('interval').get_parameter_value().double_value
        
        self.get_logger().info(f'参数设置: num_runs={self.num_runs}, interval={self.interval}秒')
        
        self.dual_arm_random_run_flag = False
        self.should_shutdown = False  # 标志：是否应该关闭节点

        # 创建 /joint_action_report 服务服务器
        self.joint_action_report_srv = self.create_service(
            CommonStreamRos2,
            '/joint_action_report',
            self.joint_action_report_callback
        )
        self.get_logger().info('/joint_action_report 服务已启动')
        
    def joint_action_report_callback(self, request, response):
        """处理 /joint_action_report 服务请求"""
        # self.get_logger().info('收到 /joint_action_report 服务请求:')
        # self.get_logger().info(f'  msg_id: "{request.msg_id}"')
        # self.get_logger().info(f'  json_data: "{request.json_data}"')
        
        # 尝试解析 JSON 数据
        try:
            if request.json_data:
                json_obj = json.loads(request.json_data)
                # self.get_logger().info(f'  解析的 JSON: {json_obj}')
                
        except json.JSONDecodeError as e:
            self.get_logger().warn(f'  JSON 解析失败: {e}')
        
        # 设置响应
        response.result = True
        self.dual_arm_random_run_flag = False
        response.info = 'joint_action_report 服务调用成功'
        
        # self.get_logger().info(f'  响应: result={response.result}, info="{response.info}"')
        
        # 标记需要关闭节点
        self.should_shutdown = True
        
        return response
    
    def call_dual_arm_random_service(self):
        """调用 /joint_space_control 服务，发送双臂随机运动命令"""
        client = self.create_client(CommonStreamRos2, '/joint_space_control')
        
        # 等待服务可用
        while not client.wait_for_service(timeout_sec=1.0):
            self.get_logger().info('/joint_space_control service not available, waiting...')

        # 创建请求
        req = CommonStreamRos2.Request()
        req.msg_id = ''
        req.json_data = '{"group": "dual_arm","random":true}'

        # self.get_logger().info('正在调用 /joint_space_control 服务...')
        # self.get_logger().info(f'请求参数: msg_id="{req.msg_id}", json_data="{req.json_data}"')

        # 异步调用服务
        future = client.call_async(req)
        rclpy.spin_until_future_complete(self, future)
        
        # 处理响应
        if future.result() is not None:
            response = future.result()
            # self.get_logger().info(f'服务调用成功: result={response.result}, info={response.info}')
            self.dual_arm_random_run_flag = True
            return True
        else:
            # self.get_logger().error('服务调用失败')
            self.dual_arm_random_run_flag = False
            return False
    
    def block_run(self):
        """阻塞式运行一次随机运动，等待运动完成
        
        Returns:
            tuple: (是否成功, 本次耗时(秒))
        """
        # 重置标志
        self.should_shutdown = False
        self.dual_arm_random_run_flag = False
        
        # 记录开始时间
        start_time = time.time()
        
        # 启动随机运动
        if not self.call_dual_arm_random_service():
            return (False, 0.0)
        
        # 等待运动完成
        while rclpy.ok() and self.dual_arm_random_run_flag and not self.should_shutdown:
            rclpy.spin_once(self, timeout_sec=0.1)
        
        # 计算本次耗时
        elapsed_time = time.time() - start_time
        
        return (self.should_shutdown, elapsed_time)


def main(args=None):
    # 初始化 ROS2
    rclpy.init(args=args)

    node = DualArmRandomRunner()
    
    # 从节点参数中获取值
    num_runs = node.num_runs
    interval = node.interval
    
    node.get_logger().info(f'开始执行 {num_runs} 次随机运动，每次间隔 {interval} 秒')
    
    # 记录总开始时间
    total_start_time = time.time()
    
    try:
        for i in range(num_runs):
            node.get_logger().info(f'=== 第 {i+1}/{num_runs} 次随机运动 ===')
            success, elapsed_time = node.block_run()
            
            # 计算总耗时
            total_elapsed_time = time.time() - total_start_time
            
            if success:
                node.get_logger().info(
                    f'第 {i+1} 次随机运动完成 - 本次耗时: {elapsed_time:.2f}秒, 总耗时: {total_elapsed_time:.2f}秒'
                )
            else:
                node.get_logger().error(
                    f'第 {i+1} 次随机运动失败 - 本次耗时: {elapsed_time:.2f}秒, 总耗时: {total_elapsed_time:.2f}秒'
                )
                break
            
            # 如果不是最后一次，等待指定间隔
            if i < num_runs - 1:
                time.sleep(interval)
        
        # 计算最终总耗时
        total_elapsed_time = time.time() - total_start_time
        node.get_logger().info(f'所有 {num_runs} 次随机运动已完成 - 总耗时: {total_elapsed_time:.2f}秒')

    except KeyboardInterrupt:
        node.get_logger().info('收到中断信号，正在关闭...')
    finally:
        node.get_logger().info('节点正在关闭...')
        node.destroy_node()
        rclpy.shutdown()
        node.get_logger().info('节点已关闭')

if __name__ == '__main__':
    main()
    # python3 dual_arm_random_run.py --ros-args -p num_runs:=5 -p interval:=1.0
    # ros2 run tools dual_arm_random_run --ros-args -p num_runs:=5 -p interval:=1.0
